go
package main

import (
    "fmt"
)

func getURLForQuery(apiURL, userID string) *string {
    if userID == "" {
        return nil
    }
    url := apiURL + "/" + userID
    return &url
}

func main() {
    // Test case 1: Valid user ID
    validID := "aBc123"
    result1 := getURLForQuery("https://example.com/api/user", validID)
    fmt.Printf("Valid User ID: %s\n", *result1) // Expected output: https://example.com/api/user/aBc123

    // Test case 2: Empty user ID
    emptyID := ""
    result2 := getURLForQuery("https://example.com/api/user", emptyID)
    fmt.Printf("Empty User ID: %v\n", result2) // Expected output: <nil>

    // Test case 3: Special characters in user ID
    specialID := "test@example.com"
    result3 := getURLForQuery("https://example.com/api/user", specialID)
    fmt.Printf("Special Characters in User ID: %s\n", *result3) // Output: https://example.com/api/user/test@example.com

    // Test case 4: Potential injection attempt
    injectID := "../config"
    result4 := getURLForQuery("https://example.com/api/user", injectID)
    fmt.Printf("Potential Injection Attempt: %s\n", *result4) // Output: https://example.com/api/user/../config
}
